'use strict';
const artists=window.ARTISTS,main=document.querySelector('main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themes={all:'All perspectives',identity:'Identity & community',power:'Power & politics',nature:'Nature & place',experiment:'Experiment & perception',popular:'Popular culture'};
const themeIds={identity:['01','02','07','10','14','15','19','23','25','27','31','33','34','36','39','40','42','45','51'],power:['02','04','05','08','15','18','20','21','22','29','31','33','34','37','39','40','42','51'],nature:['01','06','11','13','14','18','19','21','28','41','43','46'],experiment:['03','04','06','07','09','11','12','16','17','22','27','28','32','35','37','38','41','43','44','45','47','48','50'],popular:['05','08','12','13','23','24','25','26','29','30','49','51']};
let view='explore',current=null,query='',theme='all',medium='all',page=0,era='all',eventPage=0,game=null,brief=null,storageAvailable=true;
let notes={},discoveries=new Set(),compareIds=['41','20'];
try{notes=JSON.parse(sessionStorage.getItem('art-context-notes')||'{}');if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};discoveries=new Set(JSON.parse(sessionStorage.getItem('art-context-discoveries')||'[]').filter(id=>artists.some(a=>a.id===id)));const stored=JSON.parse(sessionStorage.getItem('art-context-compare')||'null');if(Array.isArray(stored)&&stored.length===2&&stored.every(id=>artists.some(a=>a.id===id)))compareIds=stored;}catch{storageAvailable=false;notes={}}
function persist(key,value){try{sessionStorage.setItem('art-context-'+key,JSON.stringify(value));return true}catch{storageAvailable=false;return false}}
function announce(s){document.querySelector('#announce').textContent=s}
function initials(a){return a.name==='Banksy'?'?':a.name.split(' ').slice(0,2).map(x=>x[0]).join('')}
function byId(id){return artists.find(a=>a.id===id)}
function cardImage(a){return a.gallery[0]?.path||a.portrait?.path||null}
function counts(){document.querySelector('#note-count').textContent=Object.values(notes).filter(n=>typeof n==='string'&&n.trim()).length;document.querySelector('#compare-count').textContent=compareIds.length}
function stop(){if('speechSynthesis'in window)speechSynthesis.cancel();document.querySelector('#stop').hidden=true}
function start(next){stop();view=next;document.querySelectorAll('nav button').forEach(b=>{const on=b.dataset.view===(next==='artist'?'explore':next);b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});counts()}
function focusMain(){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
function listenButton(text,label='Listen',small=false){return `<button class="button secondary ${small?'small':''}" data-speak="${esc(text)}">◖)) ${esc(label)}</button>`}
function voice(){if(!('speechSynthesis'in window))return null;return speechSynthesis.getVoices().find(v=>v.localService&&v.lang.toLowerCase().startsWith('en'))||null}
function voiceStatus(){const ok=Boolean(voice());document.querySelectorAll('[data-speak]').forEach(b=>{b.disabled=!ok;if(ok)b.removeAttribute('title');else b.title='An installed local English voice is required.'});document.querySelectorAll('[data-voice-note]').forEach(n=>n.textContent=ok?'Read at your pace, or listen with a voice on this device.':'A local English voice is unavailable on this device. All text is available to read.');}
function speak(text){const v=voice();if(!v)return;stop();const u=new SpeechSynthesisUtterance(text);u.voice=v;u.lang=v.lang;u.rate=.94;u.onend=u.onerror=()=>document.querySelector('#stop').hidden=true;speechSynthesis.speak(u);document.querySelector('#stop').hidden=false;}
function explore(focus=true){start('explore');current=null;const hero=byId('41').gallery[0];main.innerHTML=`<section class="hero"><div><p class="kicker"><span class="tiny-dot" aria-hidden="true"></span>51 ARTISTS · SIX CENTURIES · GRADES 7–8</p><h1>Look closer.<br><em>Think bigger.</em></h1><p class="hero-copy">Art records lives. Challenges power. Changes the way we see. Meet the artists, unpack their ideas, and build a perspective of your own.</p><div class="actions"><button class="button" data-action="surprise">Find a new perspective</button><button class="button secondary" data-view="challenges">Take the timeline challenge</button></div></div><div class="hero-art"><img src="${esc(hero.path)}" alt="${esc(hero.alt)}"><div class="hero-note"><b>51</b>different<br>perspectives</div><div class="art-caption"><strong>A wave that travelled<br>around the world.</strong><span>Hokusai · The Great Wave · c. 1830–1832<br>Explore images, ideas, and their impact.</span></div></div></section><section class="topic-strip" aria-label="Ways into the collection"><button data-topic="identity"><span class="symbol" aria-hidden="true">◎</span><strong>Whose story gets told?</strong><span>Identity, representation, and belonging.</span></button><button data-topic="power"><span class="symbol" aria-hidden="true">✳</span><strong>Can an image challenge power?</strong><span>Public space, protest, and patronage.</span></button><button data-topic="experiment"><span class="symbol" aria-hidden="true">◈</span><strong>What counts as art?</strong><span>New materials. Different ways of seeing.</span></button></section><section aria-labelledby="browse-title"><div class="section-head"><div><p class="kicker">THE ARTIST INDEX</p><h2 id="browse-title">Choose your starting point.</h2><p>Follow a question, a medium, or an artist who catches your eye.</p></div><span class="count" id="result-count"></span></div><div class="browse-controls"><label><span class="sr-only">Search artists, movements, media, and places</span><input type="search" id="artist-search" placeholder="Search an artist, movement, medium, or place…" value="${esc(query)}"></label><label><span class="sr-only">Filter by medium</span><select id="medium-filter"><option value="all">All media</option><option value="painting">Painting & fresco</option><option value="sculpture">Sculpture & installation</option><option value="print">Printmaking</option><option value="photo">Photography</option><option value="mixed">Mixed media & textiles</option></select></label></div><div class="filters" role="group" aria-label="Filter by perspective">${Object.entries(themes).map(([id,label])=>`<button class="filter" data-theme="${id}" aria-pressed="${theme===id}">${label}</button>`).join('')}</div><div id="artist-results"></div></section><section class="studio-banner"><div><p class="kicker">MAKE SOMETHING WORTH TALKING ABOUT</p><h2>Your next idea starts with a question.</h2><p>Try a creative brief. Compare two artists. Write a claim you can support.</p></div><button class="button accent" data-view="challenges">Enter the challenge lab</button></section>`;document.querySelector('#medium-filter').value=medium;renderResults();document.querySelector('#artist-search').addEventListener('input',e=>{query=e.target.value;page=0;renderResults()});document.querySelector('#medium-filter').addEventListener('change',e=>{medium=e.target.value;page=0;renderResults()});if(focus)focusMain()}
function mediaMatch(a){const m=a.media.join(' ').toLowerCase();return medium==='all'||medium==='painting'&&/paint|fresco|tempera|watercolour/.test(m)||medium==='sculpture'&&/sculpture|installation|construction/.test(m)||medium==='print'&&/print|etching|woodblock/.test(m)||medium==='photo'&&a.media.includes('Photography')||medium==='mixed'&&/mixed|textile|glass|digital/.test(m)}
function filtered(){const q=query.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return artists.filter(a=>(theme==='all'||themeIds[theme].includes(a.id))&&mediaMatch(a)&&[a.name,a.movement,a.place,a.media.join(' '),a.intro,...a.works.map(w=>w.title)].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q))}
function renderResults(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages-1);document.querySelector('#result-count').textContent=`${list.length} OF 51 ARTISTS`;document.querySelector('#artist-results').innerHTML=`<div class="grid">${list.length?list.slice(page*12,page*12+12).map(a=>`<button class="artist-card" data-artist="${a.id}" aria-label="Explore ${esc(a.name)}"><div class="card-image">${cardImage(a)?`<img class="${a.gallery.length?'':'portrait'}" src="${esc(cardImage(a))}" alt="" loading="lazy">`:`<div class="initial-poster" aria-hidden="true">${esc(initials(a))}</div>`}<span class="image-type">${a.gallery.length?'WORK IN FOCUS':a.portrait?'ARTIST PORTRAIT':'ARTIST PROFILE'}</span>${discoveries.has(a.id)?'<span class="card-marker" aria-label="Challenge completed">✓</span>':''}</div><div class="card-body"><p class="period">${esc(a.movement)}</p><h3>${esc(a.name)}</h3><p class="meta">${esc(a.dates)}<br>${esc(a.media.slice(0,2).join(' · '))}</p></div></button>`).join(''):`<div class="results-empty"><h3>No artists match that combination.</h3><p>Try a shorter search or clear the filters.</p><button class="button secondary" data-action="reset-filters">Reset filters</button></div>`}</div>${list.length?`<div class="pager"><button class="button secondary small" data-action="prev-artists" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1} of ${pages}</span><button class="button secondary small" data-action="next-artists" ${page===pages-1?'disabled':''}>Next artists</button></div>`:''}`;}
function creditHTML(g){return `<details class="credit"><summary>Image credit & reuse details</summary><p>${esc(g.credit)}<br>${esc(g.changes||'Resized for this gallery.')}<br>Source: ${esc(g.source)}<br>Licence: ${esc(g.licenseUrl||'Public-domain designation; see source record.')}${g.rightsBasis?'<br>Underlying work: '+esc(g.rightsBasis):''}</p></details>`}
function artworkPanel(a,g,index){return `<figure class="art-panel"><button data-enlarge="${index}" aria-label="Enlarge ${esc(g.title)}"><img src="${esc(g.path)}" alt="${esc(g.alt)}"></button><figcaption><strong>${esc(g.title)}</strong>${esc(g.date||'Date not verified')} · ${esc(a.name)}<br><span class="small-copy">A reproduced work to look at closely. Tap to enlarge.</span>${creditHTML(g)}</figcaption></figure>`}
function noteEditor(id,prompt){return `<label class="label" for="note-${id}">Your claim, evidence & connection</label><textarea class="note-editor" id="note-${id}" data-note="${id}" maxlength="2500" placeholder="I think… The visual evidence is… This connects to…">${esc(notes[id]||'')}</textarea><p class="note-help">${esc(prompt)} Notes stay in this tab; export them before leaving.</p><p class="note-status" id="note-status-${id}" role="status"></p>`}
function profile(id){const a=byId(id);if(!a)return;start('artist');current=a;const order=[Number(id)%3,(Number(id)+2)%3,(Number(id)+1)%3];const avatar=a.portrait?`<img class="avatar" src="${esc(a.portrait.path)}" alt="Portrait of ${esc(a.name)}">`:`<span class="avatar initial-avatar" aria-label="${a.name==='Banksy'?'Anonymous artist symbol':'Initials; no portrait is included'}">${esc(initials(a))}</span>`;main.innerHTML=`<button class="back" data-view="explore">Back to the artist index</button><div class="profile-head"><div class="profile-ident">${avatar}<div><p class="kicker">${esc(a.movement)}</p><h1>${esc(a.name)}</h1><p class="meta">${esc(a.dates)} · ${esc(a.place)}</p></div></div><div class="actions">${listenButton(a.name+'. '+a.intro+' Media: '+a.media.join(', '))}<button class="button accent" data-compare="${a.id}">Compare this artist</button></div></div><div class="profile-overview"><div>${a.gallery.length?artworkPanel(a,a.gallery[0],0):`<section class="portrait-study"><p class="kicker">START WITH THE ARTIST</p>${a.portrait?`<img src="${esc(a.portrait.path)}" alt="Portrait of ${esc(a.name)}">`:`<div class="large-initial" aria-hidden="true">${esc(initials(a))}</div>`}<h2>Read the work.<br>Question the context.</h2><p>This edition includes written studies of significant works below. No unverified artwork reproduction or substitute is presented as an original.</p>${a.portrait?creditHTML(a.portrait):''}</section>`}</div><section class="profile-summary"><p class="kicker">THE QUICK TAKE</p><p class="lead">${esc(a.intro)}</p><span class="label">Media & materials</span><div class="chips">${a.media.map(m=>`<button class="chip" data-medium="${esc(m)}" aria-label="Explain ${esc(m)}">${esc(m)}</button>`).join('')}</div><div class="movement"><span class="label">Something worth knowing</span><ul class="profile-facts">${a.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div><p class="voice-note" data-voice-note></p>${a.portrait?creditHTML(a.portrait):''}</section></div><div class="content-grid"><section class="panel"><p class="kicker">A CAREER IN CONTEXT</p><h2>Three moments on the timeline.</h2><ol class="mini-timeline">${a.timeline.map(t=>`<li><span class="year">${esc(t.dateLabel||t.year)}</span><span>${esc(t.text)}</span></li>`).join('')}</ol><div class="actions"><button class="button secondary small" data-view="timeline">See the bigger timeline</button></div></section><section class="panel mint"><p class="kicker">LOOK · INTERPRET · QUESTION</p><h2>What would you ask?</h2><p>${esc(a.quiz.question)}</p><p class="small-copy">Start with visible evidence. Then use historical context. Separate a documented fact from a personal interpretation.</p>${listenButton(a.quiz.question,'Read the question',true)}</section></div><section style="margin-top:35px" aria-labelledby="works-title"><div class="section-head"><div><p class="kicker">FAMOUS & SIGNIFICANT WORKS</p><h2 id="works-title">More than a title.</h2></div></div><p class="work-status">${esc(a.workStatus)} Dates can refer to a series, an edition, or a documented event; those distinctions are identified.</p><div class="work-studies">${a.works.map(w=>`<article class="work-study"><h3>${esc(w.title)}</h3><div class="work-date">${esc(w.date)} · ${esc(w.medium)}</div><p>${esc(w.description)}</p></article>`).join('')}</div>${a.gallery.length>1?`<div class="work-studies">${a.gallery.slice(1).map((g,i)=>artworkPanel(a,g,i+1)).join('')}</div>`:''}</section><div class="content-grid"><section class="panel lime"><p class="kicker">ART & SOCIETY</p><h2>Why did it matter beyond the studio?</h2><p>${esc(a.society)}</p><p class="analysis-label">Educational synthesis · consider other viewpoints</p>${listenButton(a.society,'Listen to this context',true)}</section><section class="panel"><p class="kicker">ART & HISTORY</p><h2>What changed in art?</h2><p>${esc(a.history)}</p><p class="analysis-label">Influence is shared; movements overlap</p>${listenButton(a.history,'Listen to this context',true)}</section></div><div class="content-grid"><section class="panel lilac"><p class="kicker">CHECK YOUR PERSPECTIVE</p><h2>A question with context.</h2><p>${esc(a.quiz.question)}</p><div class="answer-list">${order.map(i=>`<button class="answer" data-answer="${i}" aria-label="${esc(a.quiz.answers[i])}">${esc(a.quiz.answers[i])}</button>`).join('')}</div><p class="feedback" id="quiz-feedback" role="status">${discoveries.has(a.id)?'You have already completed this challenge. You can revisit it.':''}</p>${listenButton(a.quiz.question+' Choices: '+a.quiz.answers.join(' '),'Read question & choices',true)}</section><section class="panel coral"><p class="kicker">YOUR NOTEBOOK</p><h2>Make a claim. Back it up.</h2>${noteEditor(a.id,'Use one detail from a work and one piece of context. A different interpretation can be valid if its evidence is convincing.')}<div class="actions"><button class="button secondary small" data-view="notebook">Open my notebook</button></div></section></div><details class="profile-source"><summary>Sources & a note on interpretation</summary><p>Biographical and work references are listed below as plain text. The impact paragraphs are educational interpretations based on this context; they are not direct quotations or a claim that a single artist caused a historical change.</p>${a.sources.map(s=>`<p>${esc(s)}</p>`).join('')}</details>`;voiceStatus();focusMain()}
const eras={all:['All dates',0,3000],early:['1400–1699',1400,1699],long:['1700–1899',1700,1899],modern:['1900–1949',1900,1949],now:['1950–today',1950,3000]};
function timeline(){start('timeline');const all=artists.flatMap(a=>a.timeline.map(t=>({...t,artist:a}))).sort((a,b)=>a.year-b.year||a.artist.name.localeCompare(b.artist.name));const range=eras[era];const filtered=all.filter(t=>t.year>=range[1]&&t.year<=range[2]);const pages=Math.max(1,Math.ceil(filtered.length/18));eventPage=Math.min(eventPage,pages-1);main.innerHTML=`<section class="page-intro"><p class="kicker">ART DOESN’T HAPPEN IN A VACUUM</p><h1>Put the ideas<br><em>in order.</em></h1><p>Follow career moments across centuries. Notice who was working at the same time, and which approaches continued alongside newer ones.</p></section><div class="timeline-tools" role="group" aria-label="Choose a timeline period">${Object.entries(eras).map(([id,[label]])=>`<button class="filter" data-era="${id}" aria-pressed="${id===era}">${label}</button>`).join('')}</div><p class="small-copy">${filtered.length} documented career moments. Approximate dates and decade labels are identified; this is not a complete world history of art.</p><div class="event-list">${filtered.slice(eventPage*18,eventPage*18+18).map(t=>`<article class="event"><div class="event-year">${esc(t.dateLabel||t.year)}</div><div><button data-artist="${t.artist.id}">${esc(t.artist.name)}</button><p>${esc(t.text)}</p></div><span class="event-tag">${esc(t.artist.movement)}</span></article>`).join('')}</div><div class="pager"><button class="button secondary small" data-action="prev-events" ${eventPage===0?'disabled':''}>Previous</button><span>Page ${eventPage+1} of ${pages}</span><button class="button secondary small" data-action="next-events" ${eventPage===pages-1?'disabled':''}>Next moments</button></div><section class="studio-banner"><div><h2>Think you’ve got the sequence?</h2><p>Try arranging three art-history moments without seeing the dates.</p></div><button class="button accent" data-view="challenges">Play timeline mix-up</button></section>`;focusMain()}
function compare(){start('compare');const chosen=compareIds.map(byId);main.innerHTML=`<section class="page-intro"><p class="kicker">TWO ARTISTS. BETTER QUESTIONS.</p><h1>Different media.<br><em>Shared questions?</em></h1><p>Compare materials, context, and ideas. Similar-looking work can have different purposes; very different work can ask related questions.</p></section><div class="compare-pickers">${chosen.map((a,i)=>`<label>Artist ${i+1}<select aria-label="Artist ${i+1}" data-compare-select="${i}">${artists.map(x=>`<option value="${x.id}" ${a.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="compare-grid">${chosen.map(a=>`<article class="compare-card">${cardImage(a)?`<img src="${esc(cardImage(a))}" alt="${esc(a.gallery[0]?.alt||'Portrait of '+a.name)}">`:`<div class="initial-compare">${esc(initials(a))}</div>`}<p class="kicker">${esc(a.dates)}</p><h2>${esc(a.name)}</h2><p class="small-copy">${esc(a.gallery[0]?.title||(a.portrait?'Artist portrait':'No portrait included'))}</p><span class="label">Media</span><div class="chips">${a.media.map(m=>`<button class="chip" data-medium="${esc(m)}" aria-label="Explain ${esc(m)}">${esc(m)}</button>`).join('')}</div><span class="label">Context</span><p>${esc(a.intro)}</p><span class="label">Art & society</span><p>${esc(a.society)}</p><button class="button secondary small" data-artist="${a.id}">Explore this artist</button></article>`).join('')}</div><section class="reflection"><p class="kicker">THE COMPARISON CHALLENGE</p><h2>Go beyond “they both use colour.”</h2><p>What can one medium do that the other cannot? How does each artist’s setting or audience affect the work? Name one meaningful connection, then support it with evidence from both.</p><button class="button accent" data-action="comparison-note">Write a comparison note</button></section>`;main.querySelectorAll('[data-compare-select]').forEach(s=>s.addEventListener('change',e=>{const i=Number(e.target.dataset.compareSelect),id=e.target.value;if(compareIds[1-i]===id){announce('Choose a different artist for each side.');e.target.value=compareIds[i];return}compareIds[i]=id;persist('compare',compareIds);compare()}));focusMain()}
const gameBank=[['The Night Watch',1642,'45'],['A Sunday on La Grande Jatte is exhibited',1886,'28'],['Surprised! (Tiger in a Tropical Storm)',1891,'11'],['The Scream',1893,'38'],['Composition VIII',1923,'44'],['Castle and Sun',1928,'35'],['American Gothic',1930,'21'],['Migrant Mother',1936,'15'],['Guernica',1937,'22'],['Les Fétiches',1938,'10'],['The Migration Series is completed',1941,'42'],['Christina’s World',1948,'19'],['Campbell’s Soup Cans',1962,'26'],['Cakes',1963,'30'],['A Bigger Splash',1967,'43'],['Hollywood Africans',1983,'51'],['Tar Beach',1988,'39'],['Tuttomondo',1989,'08'],['Puppy',1992,'24'],['Michelle Obama portrait is unveiled',2018,'40']];
function newGame(){const pool=[...gameBank].sort(()=>Math.random()-.5).slice(0,3);game={cards:pool.map((x,i)=>({title:x[0],year:x[1],id:x[2],key:String(i)})),picked:[],message:'Choose the earliest work or event first. No timer, and you can rethink an answer.'};}
const briefs={identity:['Create a portrait that shows a role, community, or interest without relying on a realistic face.','Create a small visual autobiography using five objects and one deliberate omission.'],power:['Design a poster for a positive change you want to see in your school. Make the intended audience clear.','Propose a mural about whose stories are missing from a shared space. Use your own symbols.'],nature:['Show a familiar landscape changed by human choices. Decide what you want viewers to notice.','Make two views of the same place: one describes its appearance; the other communicates your experience of it.'],experiment:['Represent a piece of music using only line, shape, and colour. Explain which visual choices connect to the sound.','Make a study of one ordinary object from three viewpoints or moments, then combine them.']};
const constraints=['Use only two colours plus black and white.','Make repetition part of the meaning, not just decoration.','Include a change of scale that supports your message.','Use negative space as an important part of the design.','Combine one word with an image without simply labelling it.'];
function makeBrief(kind='identity'){brief={kind,text:briefs[kind][Math.floor(Math.random()*briefs[kind].length)],constraint:constraints[Math.floor(Math.random()*constraints.length)]}}
function challenges(){start('challenges');if(!game)newGame();if(!brief)makeBrief();main.innerHTML=`<section class="page-intro"><p class="kicker">THE CHALLENGE LAB</p><h1>Play with ideas.<br><em>Keep the evidence.</em></h1><p>Test your timeline instincts, then turn a question into a creative response. You don’t need a perfect drawing to have a worthwhile idea.</p></section><section class="panel lilac"><div class="section-head"><div><p class="kicker">TIMELINE MIX-UP</p><h2>Oldest first. What’s your order?</h2></div><button class="button secondary small" data-action="new-game">New round</button></div><div class="progress-track" aria-label="${game.picked.length} of 3 events placed"><span style="width:${game.picked.length/3*100}%"></span></div><div class="game-options">${game.cards.map(c=>`<button class="game-choice ${game.picked.includes(c.key)?'selected':''}" data-game="${c.key}" ${game.picked.includes(c.key)?'disabled':''}><strong>${esc(c.title)}</strong>${esc(byId(c.id).name)}<small>${game.picked.includes(c.key)?c.year+' · placed in sequence':'Date hidden · choose in chronological order'}</small></button>`).join('')}</div><p class="game-feedback" role="status">${esc(game.message)}</p></section><section style="margin-top:36px"><div class="section-head"><div><p class="kicker">YOUR CREATIVE BRIEF</p><h2>A constraint can unlock an idea.</h2></div></div><div class="challenge-controls"><label><span class="sr-only">Creative brief theme</span><select id="brief-theme"><option value="identity">Identity & belonging</option><option value="power">A message for change</option><option value="nature">Nature & place</option><option value="experiment">Experiment & perception</option></select></label><button class="button secondary" data-action="new-brief">Remix the brief</button></div><div class="brief"><p class="kicker">MAKE YOUR OWN RESPONSE</p><p>${esc(brief.text)}</p><span class="constraint">${esc(brief.constraint)}</span><p class="small-copy" style="margin-top:17px">Work on paper or with your school’s approved art tools. Use your own experiences and symbols; research cultural context rather than copying sacred imagery.</p>${listenButton(brief.text+' '+brief.constraint,'Read the brief',true)}</div><div class="rubric"><div><strong>Intent</strong><p>Who is the audience? What question or message drives your work?</p></div><div><strong>Choices</strong><p>How do the medium, composition, and visual details support that intent?</p></div><div><strong>Reflection</strong><p>What would you change after hearing another viewer’s interpretation?</p></div></div><section class="panel" style="margin-top:22px"><h3>Artist statement in progress</h3>${noteEditor('lab','Describe your intention, two visual decisions, and a connection to an artist in this collection.')}</section></section>`;main.querySelector('#brief-theme').value=brief.kind;main.querySelector('#brief-theme').addEventListener('change',e=>{makeBrief(e.target.value);challenges()});voiceStatus();focusMain()}
function notebook(){start('notebook');const entries=Object.entries(notes).filter(([id,text])=>typeof text==='string'&&text.trim());main.innerHTML=`<section class="page-intro"><p class="kicker">YOUR THINKING, IN PROGRESS</p><h1>Collect ideas.<br><em>Not just names.</em></h1><p>Your notes are saved for this tab’s session. Export a text copy before you close it or change devices. No names or accounts needed.</p></section><div class="notebook-top"><p class="session-label">${entries.length} notebook ${entries.length===1?'entry':'entries'} · ${discoveries.size} of 51 context challenges completed</p><button class="button" data-action="export-notes" ${entries.length?'':'disabled'}>Export my notes</button></div>${entries.length?entries.map(([id,text])=>`<article class="notebook-card"><p class="note-meta">${id==='lab'?'CREATIVE BRIEF':id==='comparison'?'COMPARISON':'ARTIST REFLECTION'}</p><h2>${esc(byId(id)?.name||(id==='lab'?'My artist statement':'My comparison'))}</h2><p>${esc(text)}</p><div class="actions">${byId(id)?`<button class="button secondary small" data-artist="${id}">Revisit & edit</button>`:`<button class="button secondary small" data-edit-note="${id}">Edit note</button>`}<button class="button secondary small" data-delete-note="${id}">Delete this note</button></div></article>`).join(''):`<div class="empty-notes"><h2>Your first idea is waiting.</h2><p>Visit an artist and make a claim using a visual detail and a piece of context.</p><button class="button" data-action="surprise">Find an artist</button></div>`}<p class="small-copy">Exported files are saved through your device’s download system. On a shared school device, follow your teacher’s instructions for saving work.</p>`;focusMain()}
function comparisonNote(){start('notebook');main.innerHTML=`<button class="back" data-view="compare">Back to the comparison</button><section class="page-intro"><p class="kicker">A CONNECTION WITH EVIDENCE</p><h1>Put the comparison<br><em>into words.</em></h1><p>${esc(compareIds.map(id=>byId(id).name).join(' & '))}</p></section><section class="panel coral">${noteEditor('comparison','Name a meaningful connection, support it with one detail from each artist, then explain a difference that matters.')}<div class="actions"><button class="button" data-view="notebook">View my notebook</button></div></section>`;focusMain()}
function route(next){if(next==='explore')explore();if(next==='timeline')timeline();if(next==='compare')compare();if(next==='challenges')challenges();if(next==='notebook')notebook();}
document.addEventListener('input',e=>{if(!e.target.dataset.note)return;const id=e.target.dataset.note;notes[id]=e.target.value;const saved=persist('notes',notes);const n=document.querySelector('#note-status-'+id);if(n)n.textContent=saved?'Saved for this tab’s session.':'Kept in this open page. Browser storage is unavailable; export before refreshing.';counts()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){route(b.dataset.view);return}if(b.dataset.artist){profile(b.dataset.artist);return}if(b.dataset.medium){explainMedium(b.dataset.medium);return}if(b.dataset.speak){speak(b.dataset.speak);return}if(b.dataset.theme){theme=b.dataset.theme;page=0;main.querySelectorAll('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderResults();announce(`${filtered().length} ${filtered().length===1?'artist matches':'artists match'}`);return}if(b.dataset.topic){theme=b.dataset.topic;query='';medium='all';page=0;explore(false);main.querySelector('#browse-title').scrollIntoView({block:'start'});main.querySelector(`[data-theme="${theme}"]`).focus({preventScroll:true});return}if(b.dataset.era){era=b.dataset.era;eventPage=0;timeline();return}if(b.dataset.compare){if(compareIds.includes(b.dataset.compare)){compare()}else{compareIds=[compareIds[1],b.dataset.compare];persist('compare',compareIds);compare()}return}if(b.dataset.enlarge!==undefined&&current){const g=current.gallery[Number(b.dataset.enlarge)];const d=document.createElement('dialog');d.className='art-dialog';d.setAttribute('aria-label',g.title);d.innerHTML=`<button class="close" aria-label="Close enlarged artwork">×</button><img src="${esc(g.path)}" alt="${esc(g.alt)}"><p><strong>${esc(g.title)}</strong> · ${esc(current.name)} · ${esc(g.date)}</p>${creditHTML(g)}`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return}if(b.dataset.answer!==undefined&&current){const correct=Number(b.dataset.answer)===current.quiz.correct;const feedback=document.querySelector('#quiz-feedback');if(correct){b.classList.add('correct');discoveries.add(current.id);persist('discoveries',[...discoveries]);feedback.textContent='Connection made. '+current.quiz.answers[current.quiz.correct]+' Use this idea in your reflection.';main.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true)}else{b.classList.add('wrong');feedback.textContent='Reconsider the context above, then try another answer. A convincing explanation needs evidence.'}return}if(b.dataset.game!==undefined){const c=game.cards.find(x=>x.key===b.dataset.game),next=game.cards.filter(x=>!game.picked.includes(x.key)).sort((a,b)=>a.year-b.year)[0];if(c.key===next.key){game.picked.push(c.key);game.message=game.picked.length===3?'Sequence solved: '+[...game.cards].sort((a,b)=>a.year-b.year).map(x=>x.year+' · '+x.title).join(' / '):`${c.year}: ${c.title}. Now choose the next event.`}else game.message='That is not the earliest remaining event. Compare the artists’ periods and try again.';const y=window.scrollY;challenges();window.scrollTo({top:y,behavior:'instant'});return}if(b.dataset.deleteNote){askConfirmation('Delete this notebook entry?',()=>{delete notes[b.dataset.deleteNote];persist('notes',notes);notebook()});return}if(b.dataset.editNote){if(b.dataset.editNote==='comparison')comparisonNote();else challenges();return}const action=b.dataset.action;if(action==='surprise')profile(artists[Math.floor(Math.random()*artists.length)].id);if(action==='reset-filters'){query='';theme='all';medium='all';page=0;explore(false);main.querySelector('#artist-search').focus()}if(action==='prev-artists'||action==='next-artists'){page+=action==='next-artists'?1:-1;renderResults();main.querySelector('#browse-title').scrollIntoView({block:'start'});main.querySelector('.artist-card')?.focus({preventScroll:true})}if(action==='prev-events'||action==='next-events'){eventPage+=action==='next-events'?1:-1;timeline()}if(action==='new-game'){newGame();const y=window.scrollY;challenges();window.scrollTo({top:y,behavior:'instant'})}if(action==='new-brief'){const y=window.scrollY;makeBrief(brief.kind);challenges();window.scrollTo({top:y,behavior:'instant'})}if(action==='comparison-note')comparisonNote();if(action==='teacher'){stop();document.querySelector('#teacher').showModal()}if(action==='close-teacher')document.querySelector('#teacher').close();if(action==='clear-session'){askConfirmation('Clear this tab’s Art in Context notes and completed challenges? Export any notes you want to keep first.',()=>{notes={};discoveries.clear();for(const key of ['notes','discoveries']){try{sessionStorage.removeItem('art-context-'+key)}catch{}}counts();document.querySelector('#teacher-status').textContent='This tab’s notes and discoveries were cleared.';if(view==='notebook')notebook();else main.querySelectorAll('[data-note]').forEach(n=>n.value='')})}if(action==='export-notes'){const text='ART IN CONTEXT — MY NOTEBOOK\n\n'+Object.entries(notes).filter(([,t])=>typeof t==='string'&&t.trim()).map(([id,t])=>(byId(id)?.name||(id==='lab'?'My artist statement':'My comparison'))+'\n'+t).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='art-in-context-notebook.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Notebook export requested. Check your device’s downloads.')}});
document.querySelector('#stop').onclick=stop;if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',voiceStatus);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);
document.querySelector('#source-list').innerHTML=artists.map(a=>`<section class="source-entry"><h3>${esc(a.name)}</h3><p>${a.sources.map(esc).join('<br>')}</p>${[...(a.portrait?[a.portrait]:[]),...a.gallery].map(g=>`<p><strong>${esc(g.title||'Artist portrait')}</strong><br>${esc(g.credit)}<br>${esc(g.changes||'Responsive display.')}<br>Source: ${esc(g.source)}<br>Licence: ${esc(g.licenseUrl||'Public domain; see source record.')}${g.rightsBasis?'<br>Underlying work: '+esc(g.rightsBasis):''}</p>`).join('')}</section>`).join('');
explore(false);

function explainMedium(label){
 const definitions=[[/fresco/i,'Pigment is applied to fresh lime plaster. As the plaster sets, the colour becomes part of the wall surface. This requires planning the sections that can be painted while they are wet.'],[/tempera/i,'Pigment is mixed with a binder, often egg in egg tempera. It can produce fine detail and carefully layered, quick-drying marks. Check the work record: not every paint called tempera uses egg.'],[/oil/i,'Pigments are mixed with a drying oil. The slower drying time allows blending, layering, and changes to the painted surface. The support might be wood, canvas, or another material.'],[/acrylic/i,'Pigments are held in an acrylic polymer binder. Acrylic paint usually dries quickly and can create thin washes or thick, opaque areas.'],[/watercolour/i,'Pigment and a water-soluble binder are applied with water, usually to paper. Transparent layers can let the brightness of the paper remain visible.'],[/woodblock/i,'A design is carved into a wooden block. Ink on the raised surface transfers to paper. Colour prints often require separate blocks and careful alignment.'],[/etching/i,'Lines are bitten into a metal plate using a controlled chemical process. Ink sits in the recessed lines and is transferred to paper under pressure.'],[/print/i,'An image is transferred from a prepared surface to another surface, usually paper. Processes include relief, intaglio, lithography, and screenprinting. An edition can contain multiple original impressions.'],[/photograph/i,'Light is recorded using a camera. Framing, timing, lighting, staging, processing, and editing can all influence what a photograph communicates.'],[/installation/i,'An arrangement of objects, materials, light, or sound creates an experience in a space. A viewer’s position and movement may be important parts of the work.'],[/glass/i,'Glass can act as a surface, a transparent layer, or a three-dimensional material. Light, reflection, and the viewer’s position can change what is visible.'],[/sculpture|clay/i,'Three-dimensional form can be carved, modelled, cast, assembled, or fabricated. A sculpture’s material and changing viewpoints can be central to its meaning.'],[/textile/i,'Fibres and fabrics are shaped through processes such as weaving, stitching, or assembling layers. A textile work can combine image, pattern, words, and physical texture.'],[/digital/i,'An artist uses electronic tools to create an image. The device offers a different set of marks, layers, editing options, and ways to share the result.'],[/mixed/i,'Two or more materials or processes are combined in a work. Ask what each material contributes rather than treating the combination as only decoration.'],[/mural/i,'An artwork is made for or attached to a wall. Its scale, architecture, location, and public audience help shape how it is understood. Fresco is one technique for making a mural.'],[/stencil/i,'A cut or blocked shape controls where pigment reaches a surface. The same stencil can repeat an image, while colour and location change its effect.'],[/drawing/i,'Marks made with tools such as pencil, chalk, charcoal, or ink investigate line, tone, form, and ideas. A drawing can be a plan or an independent artwork.'],[/film|performance/i,'An artwork unfolds through time. Movement, sequence, duration, and the relationship to an audience become artistic materials.'],[/writing/i,'Words can form part of an artist’s practice through books, poems, theories, captions, or statements. Text can work alongside an image or as a separate work.'],[/design/i,'Visual choices are organised for an object, communication, or space. Purpose, audience, materials, and production methods shape the result.'],[/paint/i,'Pigments held in a binder are applied to a surface. The binder, support, tools, and layering affect the result; compare the exact medium given for each work.']];
 const text=definitions.find(([re])=>re.test(label))?.[1]||'Check the specific artwork’s materials and process. The medium influences what an artist can make and how viewers experience it.';
 const d=document.createElement('dialog');d.setAttribute('aria-label',label+' explained');d.innerHTML=`<button class="close" aria-label="Close medium explanation">×</button><p class="kicker">MATERIALS MATTER</p><h2>${esc(label)}</h2><p>${esc(text)}</p>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();
}

function askConfirmation(message,confirmed){
 const d=document.createElement('dialog');d.setAttribute('aria-label','Confirm notebook change');d.innerHTML=`<p class="kicker">YOUR NOTEBOOK</p><h2>Keep or clear?</h2><p>${esc(message)}</p><div class="actions"><button class="button secondary" data-cancel>Keep my work</button><button class="button" data-confirm>Clear this work</button></div>`;document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=()=>{d.close();confirmed()};d.addEventListener('close',()=>d.remove());d.showModal();d.querySelector('[data-cancel]').focus();
}
